insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 27, 19, 'O rico dormirá, mas não será recolhido; ele abrirá seus olhos, e nada mais há para si.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 27, 20, 'Medos o tomarão como águas; um turbilhão o arrebatará de noite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 27, 21, 'O vento oriental o levará, e ele partirá; e toma-o de seu lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 27, 22, 'E o atacará sem o poupar, [enquanto] ele tenta fugir de seu poder.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 27, 23, 'Baterá palmas por causa dele, e desde seu lugar lhe assoviará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 28, 1, 'Certamente há minas para a prata, e o ouro lugar onde o derretem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 28, 2, 'O ferro é tirado do solo, e da pedra se funde o cobre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 28, 3, 'O [homem] põe fim às trevas, e investiga em toda extremidade, as pedras que estão na escuridão e nas mais sombrias trevas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 28, 4, 'Abre um poço onde não há morador, lugares esquecidos por quem passa a pé; pendurados longe da humanidade, vão de um lado para o outro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 28, 5, 'Da terra o pão procede, e por debaixo ela é transformada como que pelo fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 28, 6, 'Suas pedras são o lugar da safira, e contém pó de ouro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 28, 7, 'A ave de rapina não conhece essa vereda; os olhos do falcão não a viram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 28, 8, 'Os filhotes de animais ferozes nunca a pisaram, nem o feroz leão passou por ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 28, 9, '[O homem] põe sua mão no rochedo, e revolve os montes desde a raiz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 28, 10, 'Cortou canais pelas rochas, e seus olhos veem tudo o que é precioso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 28, 11, 'Ele tapa os rios desde suas nascentes, e faz o oculto sair para a luz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 28, 12, 'Porém onde se achará a sabedoria? E onde está o lugar da inteligência?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 28, 13, 'O ser humano não conhece o valor dela, nem ela é achada na terra dos viventes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 28, 14, 'O abismo diz: Não está em mim; E o mar diz: Nem comigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 28, 15, 'Nem por ouro fino se pode comprar, nem se pesar em troca de prata.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 28, 16, 'Não pode ser avaliada com ouro de Ofir, nem com ônix precioso, nem com safira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 28, 17, 'Não se pode comparar com ela o ouro, nem o cristal; nem se pode trocar por joia de ouro fino.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 28, 18, 'De coral nem de quartzo não se fará menção; porque o preço da sabedoria é melhor que o de rubis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 28, 19, 'O topázio de Cuxe não se pode comparar com ela; nem pode ser avaliada com o puro ouro fino.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 28, 20, 'De onde, pois, vem a sabedoria? E onde está o lugar da inteligência?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 28, 21, 'Porque encoberta está aos olhos de todo vivente, e é oculta a toda ave do céu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 28, 22, 'O perdição e a morte dizem: Com nossos ouvidos ouvimos sua fama.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 28, 23, 'Deus entende o caminho dela, e ele conhece seu lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 28, 24, 'Porque ele enxerga até os confins da terra, e vê tudo [o que há] debaixo de céus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 28, 25, 'Quando ele deu peso ao vento, e estabeleceu medida para as águas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 28, 26, 'Quando ele fez lei para a chuva, e caminho para o relâmpago dos trovões,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 28, 27, 'Então ele a viu, e relatou; preparou-a, e também a examinou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 28, 28, 'E disse ao homem: Eis que o temor ao Senhor é a sabedoria, e o desviar-se do mal [é] a inteligência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 29, 1, 'E Jó continuou a falar seu discurso, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 29, 2, 'Ah quem me dera que fosse como nos meses passados! Como nos dias em que Deus me guardava!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 29, 3, 'Quando ele fazia brilhar sua lâmpada sobre minha cabeça, e eu com sua luz caminhava pelas trevas,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 29, 4, 'Como era nos dias de minha juventude, quando a amizade de Deus estava sobre minha tenda;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 29, 5, 'Quando o Todo-Poderoso ainda estava comigo, meus filhos ao redor de mim;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 29, 6, 'Quando eu lavava meus passos com manteiga, e da rocha me corriam ribeiros de azeite!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 29, 7, 'Quando eu saía para a porta da cidade, [e] na praça preparava minha cadeira,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 29, 8, 'Os rapazes me viam, e abriam caminho; e os idosos se levantavam, e ficavam em pé;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 29, 9, 'Os príncipes se detinham de falar, e punham a mão sobre a sua boca;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 29, 10, 'A voz dos líderes se calava, e suas línguas se apegavam a céu da boca;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 29, 11, 'O ouvido que me ouvia me considerava bem-aventurado, e o olho que me via dava bom testemunho de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 29, 12, 'Porque eu livrava ao pobre que clamava, e ao órfão que não tinha quem o ajudasse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 29, 13, 'A bênção do que estava a ponto de morrer vinha sobre mim; e eu fazia o coração da viúva ter grande alegria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 29, 14, 'Vestia-me de justiça, e ela me envolvia; e meu juízo era como um manto e um turbante.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 29, 15, 'Eu era olhos para o cego, e pés para o manco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 29, 16, 'Aos necessitados eu era pai; e a causa que eu não sabia, investigava com empenho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 29, 17, 'E quebrava os queixos do perverso, e de seus dentes tirava a presa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 29, 18, 'E eu dizia: Em meu ninho expirarei, e multiplicarei [meus] dias como areia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 29, 19, 'Minha raiz se estendia junto às águas, e o orvalho ficava de noite em meus ramos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 29, 20, 'Minha honra se renovava em mim, e meu arco se revigorava em minha mão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 29, 21, 'Ouviam-me, e esperavam; e se calavam ao meu conselho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 29, 22, 'Depois de minha palavra nada replicavam, e minhas razões gotejavam sobre eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 29, 23, 'Pois esperavam por mim como pela chuva, e abriam sua boca como para a chuva tardia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 29, 24, 'Se eu me ria com eles, não acreditavam; e não desfaziam a luz de meu rosto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 29, 25, 'Eu escolhia o caminho para eles, e me sentava à cabeceira; e habitava como rei entre as tropas, como o consolador dos que choram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 30, 1, 'Porém agora riem de mim os mais jovens do que eu, cujos pais eu havia desdenhado até de os pôr com os cães de meu rebanho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 30, 2, 'De que também me serviria força de suas mãos, nos quais o vigor já pereceu?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 30, 3, 'Por causa da pobreza e da fome andavam sós; roem na terra seca, no lugar desolado e deserto em trevas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 30, 4, 'Que colhiam malvas entre os arbustos, e seu alimento eram as raízes dos zimbros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 30, 5, 'Do meio [das pessoas] eram expulsos, e gritavam contra eles, como a um ladrão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 30, 6, 'Habitavam nos barrancos dos ribeiros secos, nos buracos da terra, e nas rochas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 30, 7, 'Bramavam entre os arbustos, e se ajuntavam debaixo das urtigas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 30, 8, 'Eram filhos de tolos, filhos sem nome, e expulsos de [sua] terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 30, 9, 'Porém agora sirvo-lhes de chacota, e sou para eles um provérbio de escárnio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 30, 10, 'Eles me abominam [e] se afastam de mim; porém não hesitam em cuspir no meu rosto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 30, 11, 'Pois [Deus] desatou minha corda, e me oprimiu; por isso tiraram [de si] todo constrangimento perante meu rosto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 30, 12, 'À direita os jovens se levantam; empurram meus pés, e preparam contra mim seus caminhos de destruição.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 30, 13, 'Destroem meu caminho, e promovem minha miséria, sem necessitarem que alguém os ajude.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 30, 14, 'Eles vêm [contra mim] como que por uma brecha larga, [e] revolvem-se entre a desolação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 30, 15, 'Pavores se voltam contra mim; perseguem minha honra como o vento, e como nuvem passou minha prosperidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 30, 16, 'Por isso agora minha alma se derrama em mim; dias de aflição têm me tomado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 30, 17, 'De noite meus ossos se furam em mim, e meus pulsos não descansam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 30, 18, 'Por grande força [de Deus] minha roupa está estragada; ele me prendeu como a gola de minha roupa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 30, 19, 'Lançou-me na lama, e fiquei semelhante ao pó e à cinza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 30, 20, 'Clamo a ti, porém tu não me respondes; eu fico de pé, porém tu ficas [apenas] olhando para mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 30, 21, 'Tu te tornaste cruel para comigo; com a força de tua mão tu me atacas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 30, 22, 'Levantas-me sobre o vento, [e] me fazes cavalgar [sobre ele] ; e dissolves o meu ser.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 30, 23, 'Porque eu sei que me levarás à morte; e à casa determinada a todos os viventes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 30, 24, 'Porém não se estende a mão para quem está em ruínas, quando clamam em sua opressão?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 30, 25, 'Por acaso eu não chorei pelo que estava em dificuldade, [e] minha alma não se angustiou pelo necessitado?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 30, 26, 'Quando eu esperava o bem, então veio o mal; quando eu esperava a luz, veio a escuridão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 30, 27, 'Minhas entranhas fervem, e não se aquietam; dias de aflição me confrontam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 30, 28, 'Ando escurecido, mas não pelo sol; levanto-me na congregação, e clamo por socorro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 30, 29, 'Tornei-me irmão dos chacais, e companheiro dos avestruzes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 30, 30, 'Minha pele se escureceu sobre mim, e meus ossos se inflamam de febre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 30, 31, 'Por isso minha harpa passou a ser para lamentação, e minha flauta para vozes dos que choram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 31, 1, 'Eu fiz um pacto com meus olhos; como, pois, eu olharia com cobiça para a virgem?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 31, 2, 'Pois qual é a porção [dada] por Deus acima, e a herança [dada] pelo Todo-Poderoso das alturas?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 31, 3, 'Por acaso a calamidade não é para o perverso, e o desastre para os que praticam injustiça?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 31, 4, 'Por acaso ele não vê meus caminhos, e conta todos os meus passos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 31, 5, 'Se eu andei com falsidade, e se meu pé se apressou para o engano,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 31, 6, 'Pese-me ele em balanças justas, e Deus saberá minha integridade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 31, 7, 'Se meus passos se desviaram do caminho, e meu coração seguiu meus olhos, e se algo se apegou às minhas mãos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 31, 8, 'Que eu semeie, e outro coma; e meus produtos sejam arrancados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 31, 9, 'Se foi meu coração se deixou seduzir por [alguma] mulher, ou se estive espreitei à porta de meu próximo,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 31, 10, 'Que minha mulher moa para outro, e outros se encurvem sobre ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 31, 11, 'Pois tal seria um crime vergonhoso, e delito [a ser sentenciado por] juízes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 31, 12, 'Pois seria um fogo que consumiria até à perdição, e destruiria toda a minha renda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 31, 13, 'Se desprezei o direito de meu servo ou de minha serva quando eles reclamaram comigo,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 31, 14, 'Que faria eu quando Deus se levantasse? E quando ele investigasse [a causa] ,o que eu lhe responderia?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 31, 15, 'Aquele que me fez no ventre [materno também] não fez a ele? E não nos preparou de um mesmo [modo] na madre?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 31, 16, 'Se eu neguei aos pobres o que eles desejavam, ou fiz desfalecer os olhos da viúva;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 31, 17, 'E se comi meu alimento sozinho, e o órfão não comeu dele'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 31, 18, '(Porque desde a minha juventude cresceu comigo como [se eu fosse seu pai] ,e desde o ventre de minha mãe guiei [a viúva] );'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 31, 19, 'Se eu vi alguém morrer por falta de roupa, e o necessitado sem algo que o cobrisse,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 31, 20, 'Se sua cintura não me bendisse, quando ele se esquentava com as peles de meus cordeiros;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 31, 21, 'Se levantei minha mão contra o órfão, quando vi que seria favorecido na corte judicial,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 31, 22, 'Que minha escápula caia do meu ombro, e meu braço se quebre de sua articulação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 31, 23, 'Porque o castigo de Deus era um assombro para mim, e eu não teria poder contra sua majestade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 31, 24, 'Se eu pus no ouro minha esperança, ou disse ao ouro fino: Tu és minha confiança;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 31, 25, 'Se eu me alegrei de que minha riqueza era muita, e de que minha mão havia obtido muito;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 31, 26, 'Se olhei para o sol quando brilhava, e à lua quando estava bela,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 31, 27, 'E meu coração se deixou enganar em segredo, e minha boca beijou minha mão,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 31, 28, 'Isto também seria um delito [a ser sentenciado por] juiz; porque teria negado ao Deus de cima.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 31, 29, 'Se eu me alegrei da desgraça daquele que me odiava, e me agradei quando o mal o encontrou,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 31, 30, 'Sendo que nem deixei minha boca pecar, desejando sua morte com maldição,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 31, 31, 'Se a gente da minha casa nunca tivesse dito: Quem não se satisfez da carne dada por ele?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 31, 32, 'O estrangeiro não passava a noite na rua; eu abria minhas portas ao viajante.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 31, 33, 'Se encobri minhas transgressões como as pessoas [fazem] , escondendo meu delito em meu seio;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 31, 34, 'Porque eu tinha medo da grande multidão, e o desprezo das famílias me atemorizou; então me calei, e não saí da porta:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 31, 35, 'Quem me dera se alguém me ouvisse! Eis que minha vontade é que o Todo-Poderoso me responda, e meu adversário escrevesse um relato da acusação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 31, 36, 'Certamente eu o carregaria sobre meu ombro, e o poria em mim como uma coroa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 31, 37, 'Eu lhe diria o número de meus passos, e como um príncipe eu me chegaria a ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 31, 38, 'Se minha terra clamar contra mim, e seus sulcos juntamente chorarem;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 31, 39, 'Se comi seus frutos sem [pagar] dinheiro, ou fiz expirar a alma de seus donos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 31, 40, 'Em lugar de trigo que [me] produza cardos, e ervas daninhas no lugar da cevada. [Aqui] terminam as palavras de Jó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 32, 1, 'Então aqueles três homens cessaram de responder a Jó, porque ele era justo em seus olhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 32, 2, 'Porém se acendeu a ira de Eliú, filho de Baraquel, buzita, da família de Rão; contra Jó se acendeu sua ira, porque justificava mais a si mesmo que a Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 32, 3, 'Também sua ira se acendeu contra seus três amigos, porque não achavam o que responder, ainda que tinham condenado a Jó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 32, 4, 'E Eliú tinha esperado a Jó naquela discussão, porque tinham mais idade que ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 32, 5, 'Porém quando Eliú viu que não havia resposta na boca daqueles três homens, sua ira se acendeu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 32, 6, 'Por isso Eliú, filho de Baraquel, buzita, respondeu, dizendo: Eu sou jovem e vós sois idosos; por isso fiquei receoso e tive medo de vos declarar minha opinião.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 32, 7, 'Eu dizia: Os dias falem, e a multidão de anos ensine sabedoria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 32, 8, 'Certamente há espírito no ser humano, e a inspiração do Todo-Poderoso os faz entendedores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 32, 9, 'Não são [somente] os grandes que são sábios, nem [somente] os velhos entendem o juízo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 32, 10, 'Por isso eu digo: escutai-me; também eu declararei minha opinião.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 32, 11, 'Eis que eu aguardei vossas palavras, [e] dei ouvidos a vossas considerações, enquanto vós buscáveis argumentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 32, 12, 'Eu prestei atenção a vós, porém eis que ninguém há de vós que possa convencer a Jó, [nem] que responda a suas palavras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 32, 13, 'Portanto não digais: Encontramos a sabedoria; que Deus o derrote, [e] não o homem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 32, 14, 'Jó não dirigiu suas palavras a mim, nem eu lhe responderei com vossos dizeres.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 32, 15, 'Estão pasmos, não respondem mais; faltam-lhes palavras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 32, 16, 'Esperei, pois, porém [agora] não falam; porque já pararam, [e] não respondem mais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 32, 17, 'Também eu responderei minha parte; também eu declararei minha opinião.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 32, 18, 'Porque estou cheio de palavras, e o espírito em meu ventre me obriga.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 32, 19, 'Eis que meu ventre é como o vinho que não tem abertura; e que está a ponto de arrebentar como odres novos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 32, 20, 'Falarei, para que eu me alivie; abrirei meus lábios, e responderei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 32, 21, 'Não farei eu acepção de pessoas, nem usarei de títulos lisonjeiros para com o homem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 32, 22, 'Pois não sei lisonjear; [caso contrário] ,meu Criador logo me removeria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 33, 1, 'Portanto, Jó, ouve, por favor, meus dizeres, e dá ouvidos a todas as minhas palavras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 33, 2, 'Eis que já abri minha boca; minha língua já fala debaixo do meu céu da boca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 33, 3, 'Meus dizeres pronunciarão a integridade do meu coração, e o puro conhecimento dos meus lábios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 33, 4, 'O Espírito de Deus me fez, e o sopro do Todo-Poderoso me deu vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 33, 5, 'Se puderes, responde-me; dispõe-te perante mim, e persiste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 33, 6, 'Eis que para Deus eu sou como tu; do barro também eu fui formado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 33, 7, 'Eis que meu terror não te espantará, nem minha mão será pesada sobre ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 33, 8, 'Certamente tu disseste a meus ouvidos, e eu ouvi a voz de tuas palavras,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 33, 9, '[Que diziam] : Eu sou limpo e sem transgressão; sou inocente, e não tenho culpa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 33, 10, 'Eis que [Deus] buscou pretextos contra mim, [e] me tem por seu inimigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 33, 11, 'Ele pôs meus pés no tronco, e observa todas as minhas veredas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 33, 12, 'Eis que nisto não foste justo, eu te respondo; pois Deus é maior que o ser humano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 33, 13, 'Por que razão brigas contra ele por não dar resposta às palavras do ser humano?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 33, 14, 'Contudo Deus fala uma ou duas vezes, ainda que [o ser humano] não entenda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 33, 15, 'Em sonho [ou em] visão noturna, quando o sono profundo cai sobre as pessoas, [e] adormecem na cama.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 33, 16, 'Então o revela ao ouvido das pessoas, e os sela com advertências;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 33, 17, 'Para desviar ao ser humano de sua obra, e do homem a soberba.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 33, 18, 'Para desviar a sua alma da perdição, e sua vida de passar pela espada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 33, 19, 'Também em sua cama é castigado com dores, com luta constante em seus ossos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 33, 20, 'De modo que sua vida detesta [até] o pão, e sua alma a comida deliciosa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 33, 21, 'Sua carne desaparece da vista, e seus ossos, que antes não se viam, aparecem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 33, 22, 'Sua alma se aproxima da cova, e sua vida dos que causam a morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 33, 23, 'Se com ele, pois, houver algum anjo, algum intérprete; um dentre mil, para anunciar ao ser humano o que lhe é correto,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 33, 24, 'Então [Deus] terá misericórdia dele, e [lhe] dirá: Livra-o, para que não desça à perdição; [já] achei o resgate.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 33, 25, 'Sua carne se rejuvenescerá mais do que era na infância, [e] voltará aos dias de sua juventude.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 33, 26, 'Ele orará a Deus, que se agradará dele; e verá sua face com júbilo, porque ele restituirá ao ser humano sua justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 33, 27, 'Ele olhará para as pessoas, e dirá: Pequei, e perverti o [que era] correto, o que de nada me aproveitou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 33, 28, '[Porém] Deus livrou minha alma para que eu não passasse à cova, e [agora] minha vida vê a luz!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 33, 29, 'Eis que Deus faz tudo isto duas [ou] três vezes com o ser humano,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 33, 30, 'Para desviar sua alma da perdição, e o iluminar com a luz dos viventes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 33, 31, 'Presta atenção, Jó, e ouve-me; cala-te, e eu falarei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 33, 32, 'Se tiveres o que dizer, responde-me; fala, porque eu quero te justificar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 33, 33, 'E se não, escuta-me; cala-te, e eu ensinarei sabedoria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 34, 1, 'Eliú respondeu mais, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 34, 2, 'Ouvi, vós sábios, minhas palavras; e vós, inteligentes, dai-me ouvidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 34, 3, 'Porque o ouvido prova as palavras, assim como o paladar experimenta a comida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 34, 4, 'Escolhamos para nós o que é correto, [e] conheçamos entre nós o que é bom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 34, 5, 'Pois Jó disse: Eu sou justo, e Deus tem me tirado meu direito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 34, 6, 'Por acaso devo eu mentir quanto ao meu direito? Minha ferida é dolorosa mesmo que eu não tenha transgressão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 34, 7, 'Que homem há como Jó, que bebe o escárnio como água?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 34, 8, 'E que caminha na companhia dos que praticam maldade, e anda com homens perversos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 34, 9, 'Porque disse: De nada aproveita ao homem agradar-se em Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 34, 10, 'Portanto vós, homens de bom-senso, escutai-me; longe de Deus esteja a maldade, e do Todo- Poderoso a perversidade!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 34, 11, 'Porque ele paga ao ser humano [conforme] sua obra, e faz a cada um conforme o seu caminho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 34, 12, 'Certamente Deus não faz injustiça, e o Todo-Poderoso não perverte o direito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 34, 13, 'Quem o pôs para administrar a terra? E quem dispôs a todo o mundo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 34, 14, 'Se ele tomasse a decisão, e recolhesse para si seu espírito e seu fôlego,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 34, 15, 'Toda carne juntamente expiraria, e o ser humano se tornaria em pó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 34, 16, 'Se pois há [em ti] entendimento, ouve isto: dá ouvidos ao som de minhas palavras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 34, 17, 'Por acaso quem odeia a justiça poderá governar? E condenarás tu ao Poderoso Justo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 34, 18, 'Pode, por acaso, o rei ser chamado de vil, [e] os príncipes de perversos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 34, 19, '[Quanto menos] a aquele que não faz acepção de pessoas de príncipes, nem valoriza mais o rico que o pobre! Pois todos são obras de suas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 34, 20, 'Em um momento morrem; e à meia noite os povos são sacudidos, e passam; e o poderoso será tomado sem ação humana.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 34, 21, 'Porque seus olhos estão sobre os caminhos do homem, e ele vê todos os seus passos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 34, 22, 'Não há trevas nem sombra de morte em que os que praticam maldade possam se esconder.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 34, 23, 'Pois ele não precisa observar tanto ao homem para que este possa entrar em juízo com Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 34, 24, 'Ele quebranta aos fortes sem [precisar de] investigação, e põe outros em seu lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 34, 25, 'Visto que ele conhece suas obras, de noite os trastorna, e ficam destroçados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 34, 26, 'Ele os espanca à vista pública por serem maus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 34, 27, 'Pois eles se desviaram de segui-lo, e não deram atenção a nenhum de seus caminhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 34, 28, 'Assim fizeram com que viesse a ele o clamor do pobre, e ele ouvisse o clamor dos aflitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 34, 29, 'E se ele ficar quieto, quem [o] condenará? Se ele esconder o rosto, quem o olhará? [Ele está] quer sobre um povo, quer sobre um único ser humano,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 34, 30, 'Para que a pessoa hipócrita não reine, [e] não haja ciladas ao povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 34, 31, 'Por que [não tão somente] se diz: Suportei [teu castigo] não farei mais o que é errado;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 34, 32, 'Ensina-me o que não vejo; se fiz alguma maldade, nunca mais a farei?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 34, 33, 'Será a recompensa da parte dele como tu queres, para que a recuses? És tu que escolhes, e não eu; o que tu sabes, fala.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 34, 34, 'As pessoas de entendimento dirão comigo, e o homem sábio me ouvirá;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 34, 35, 'Jó não fala com conhecimento, e a suas palavras falta prudência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 34, 36, 'Queria eu que Jó fosse provado até o fim, por causa de suas respostas comparáveis a de homens malignos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 34, 37, 'Pois ao seu pecado ele acrescentou rebeldia; ele bate as mãos [de forma desrespeitosa] entre nós, e multiplica suas palavras contra Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 35, 1, 'Eliú respondeu mais, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 35, 2, 'Pensas tu ser direito dizeres: Maior é a minha justiça do que a de Deus?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 35, 3, 'Porque disseste: Para que ela te serve? [Ou] : Que proveito terei dela mais que meu pecado?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 35, 4, 'Eu darei reposta a ti, e a teus amigos contigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 35, 5, 'Olha para os céus, e vê; e observa as nuvens, [que] são mais altas que tu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 35, 6, 'Se tu pecares, que [mal] farás contra ele? Se tuas transgressões se multiplicarem, que [mal] lhe farás?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 35, 7, 'Se fores justo, que lhe darás? Ou o que ele receberá de tua mão?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 35, 8, 'Tua perversidade [poderia afetar] a outro homem como tu; e tua justiça [poderia ser proveitosa] a [algum] filho do homem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 35, 9, '[Os aflitos] clamam por causa da grande opressão; eles gritam por causa do poder dos grandes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 35, 10, 'Porém ninguém diz: Onde está Deus, meu Criador, que dá canções na noite,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 35, 11, 'Que nos ensina mais que aos animais da terra, e nos faz sábios mais que as aves do céu?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 35, 12, 'Ali clamam, porém ele não responde, por causa da arrogância dos maus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 35, 13, 'Certamente Deus não ouvirá a súplica vazia, nem o Todo-Poderoso dará atenção a ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 35, 14, 'Quanto menos ao que disseste: que tu não o vês! Porém o juízo está diante dele; portanto espera nele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 35, 15, 'Mas agora, já que a ira dele [ainda] não está castigando, e ele não deu completa atenção à arrogância,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 35, 16, 'Por isso Jó abriu sua boca em vão, e multiplicou palavras sem conhecimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 36, 1, 'Prosseguiu Eliú ainda, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 36, 2, 'Espera-me um pouco, e eu te mostrarei que ainda há palavras a favor de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 36, 3, 'Desde longe trarei meu conhecimento, e a meu Criador atribuirei a justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 36, 4, 'Porque verdadeiramente minhas palavras não serão falsas; contigo está um que tem completo conhecimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 36, 5, 'Eis que Deus é grande, porém despreza ninguém; grande ele é em poder de entendimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 36, 6, 'Ele não permite o perverso viver, e faz justiça aos aflitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 36, 7, 'Ele não tira seus olhos do justo; ao contrário, ele os faz sentar com os reis no trono, e [assim] são exaltados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 36, 8, 'E se estiverem presos em grilhões, e detidos com cordas de aflição,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 36, 9, 'Então ele lhes faz saber as obras que fizeram, e suas transgressões, das quais se orgulharam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 36, 10, 'E revela a seus ouvidos, para que sejam disciplinados; e lhes diz, para que se convertam da maldade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 36, 11, 'Se ouvirem, e [o] servirem, acabarão seus dias em prosperidade, e seus anos em prazeres.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 36, 12, 'Porém se não ouvirem, perecerão pela espada, e morrerão sem conhecimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 36, 13, 'E os hipócritas de coração acumulam a ira [divina] ; e quando ele os amarrar, mesmo assim não clamam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 36, 14, 'A alma deles morrerá em sua juventude, e sua vida entre os pervertidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 36, 15, 'Ele livra o aflito de sua aflição, e na opressão ele revela a seus ouvidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 36, 16, 'Assim também ele pode te desviar da boca da angústia [para] um lugar amplo, onde não haveria aperto; para o conforto de tua mesa, cheia dos melhores alimentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 36, 17, 'Mas tu estás cheio do julgamento do perverso; o julgamento e a justiça te tomam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 36, 18, 'Por causa da furor, [guarda-te] para que não sejas seduzido pela riqueza, nem que um grande suborno te faça desviar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 36, 19, 'Pode, por acaso, a tua riqueza te sustentar para que não tenhas aflição, mesmo com todos os esforços de [teu] poder?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 36, 20, 'Não anseies pela noite, em que os povos são tomados de seu lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 36, 21, 'Guarda-te, e não te voltes para a maldade; pois por isto que tens sido testado com miséria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 36, 22, 'Eis que Deus é exaltado em seu poder; que instrutor há como ele?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 36, 23, 'Quem lhe indica o seu caminho? Quem poderá lhe dizer: Cometeste maldade?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 36, 24, 'Lembra-te de engrandeceres sua obra, a qual os seres humanos contemplam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 36, 25, 'Todas as pessoas a veem; o ser humano a enxerga de longe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 36, 26, 'Eis que Deus é grande, e nós não o compreendemos; não se pode descobrir o número de seus anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 36, 27, 'Ele traz para cima as gotas das águas, que derramam a chuva de seu vapor;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 36, 28, 'A qual as nuvens destilam, gotejando abundantemente sobre o ser humano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 36, 29, 'Poderá alguém entender a extensão das nuvens, [e] os estrondos de seu pavilhão?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 36, 30, 'Eis que estende sobre ele sua luz, e cobre as profundezas do mar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 36, 31, 'Pois por estas coisas ele julga aos povos, e dá alimento em abundância.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 36, 32, 'Ele cobre as mãos com o relâmpago, e dá ordens para que atinja o alvo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 36, 33, 'O trovão anuncia sua presença; o gado também [prenuncia a tempestade] que se aproxima.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 37, 1, 'Disto também o meu coração treme, e salta de seu lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 37, 2, 'Ouvi atentamente o estrondo de sua voz, e o som que sai de sua boca,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 37, 3, 'Ao qual envia por debaixo de todos os céus; e sua luz até os confins da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 37, 4, 'Depois disso brama com estrondo; troveja com sua majestosa voz; e ele não retém [seus relâmpagos] quando sua voz é ouvida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 37, 5, 'Deus troveja maravilhosamente com sua voz; ele faz coisas tão grandes que nós não compreendemos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 37, 6, 'Pois ele diz à neve: Cai sobre à terra; Como também à chuva: Sê chuva forte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 37, 7, 'Ele sela as mãos de todo ser humano, para que todas as pessoas conheçam sua obra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 37, 8, 'E os animais selvagens entram nos esconderijos, e ficam em suas tocas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 37, 9, 'Da recâmara vem o redemoinho, e dos [ventos] que espalham [vem] o frio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 37, 10, 'Pelo sopro de Deus se dá o gelo, e as largas águas se congelam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 37, 11, 'Ele também carrega de umidade as espessas nuvens, [e] por entre as nuvens ele espalha seu relâmpago.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 37, 12, 'Então elas se movem ao redor segundo sua condução, para que façam quanto ele lhes manda sobre a superfície do mundo, na terra;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 37, 13, 'Seja que ou por vara de castigo, ou para sua terra, ou por bondade as faça vir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 37, 14, 'Escuta isto, Jó; fica parado, e considera as maravilhas de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 37, 15, 'Por acaso sabes tu quando Deus dá ordem a elas, e faz brilhar o relâmpago de sua nuvem?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 37, 16, 'Conheces tu os equilíbrios das nuvens, as maravilhas daquele que é perfeito no conhecimento?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 37, 17, 'Tu, cujas vestes se aquecem quando a terra se aquieta por causa do [vento] sul,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 37, 18, 'acaso podes estender com ele os céus, que estão firmes como um espelho fundido?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 37, 19, 'Ensina-nos o que devemos dizer a ele; [pois discurso] nenhum podemos propor, por causa das [nossas] trevas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 37, 20, 'Seria contado a ele o que eu haveria de falar? Por acaso alguém falaria para ser devorado?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 37, 21, 'E agora não se pode olhar para o sol, quando brilha nos céus, quando o vento passa e os limpa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 37, 22, 'Do norte vem o esplendor dourado; em Deus há majestade temível.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 37, 23, 'Não podemos alcançar ao Todo-Poderoso; ele é grande em poder; porém ele a ninguém oprime [em] juízo e grandeza de justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 37, 24, 'Por isso as pessoas o temem; ele não dá atenção aos que [se acham] sábios de coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 38, 1, 'Então o SENHOR respondeu a Jó desde um redemoinho, e disse:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 38, 2, 'Quem é esse que obscurece o conselho com palavras sem conhecimento?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 38, 3, 'Agora cinge teus lombos como homem; e eu te perguntarei, e tu me explicarás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 38, 4, 'Onde estavas tu quando eu fundava a terra? Declara- [me] ,se tens inteligência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 38, 5, 'Quem determinou suas medidas, se tu o sabes? Ou quem estendeu cordel sobre ela?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 38, 6, 'Sobre o que estão fundadas suas bases? Ou quem pôs sua pedra angular,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 38, 7, 'Quando as estrelas do amanhecer cantavam alegremente juntas, e todos os filhos de Deus jubilavam?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 38, 8, 'Ou [quem] encerrou o mar com portas, quando transbordou, saindo da madre,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 38, 9, 'Quando eu pus nuvens por sua vestidura, e a escuridão por sua faixa;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 38, 10, 'Quando eu passei sobre ele meu decreto, e [lhe] pus portas e ferrolhos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 38, 11, 'E disse: Até aqui virás, e não passarás adiante, e aqui será o limite para a soberba de tuas ondas?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 38, 12, 'Desde os teus dias tens dado ordem à madrugada? [Ou] mostraste tu ao amanhecer o seu lugar,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 38, 13, 'Para que tomasse os confins da terra, e os perversos fossem sacudidos dela?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 38, 14, 'E [a terra] se transforma como barro [sob] o selo; [todas as coisas sobre ela] se apresentam como vestidos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 38, 15, 'E dos perversos é desviada sua luz, e o braço erguido é quebrado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 38, 16, 'Por acaso chegaste tu às fontes do mar, ou passeaste no mais profundo abismo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 38, 17, 'Foram reveladas a ti as portas da morte, ou viste as portas da sombra de morte?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 38, 18, 'Entendeste tu as larguras da terra? Declara, se sabes tudo isto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 38, 19, 'Onde está o caminho [por onde] mora a luz? E quanto às trevas, onde fica o seu lugar?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 38, 20, 'Para que as tragas a seus limites, e conheças os caminhos de sua casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 38, 21, 'Certamente tu o sabes, pois já eras nascido, e teus dias são inúmeros!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 38, 22, 'Por acaso entraste tu aos depósitos da neve, e viste os depósitos do granizo,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 38, 23, 'Que eu retenho até o tempo da angústia, até o dia da batalha e da guerra?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 38, 24, 'Onde está o caminho em que a luz se reparte, e o vento oriental se dispersa sobre a terra?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 38, 25, 'Quem repartiu um canal às correntezas de águas, e caminho aos relâmpagos dos trovões,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 38, 26, 'Para chover sobre a terra [onde] havia ninguém, [sobre] o deserto, onde não há gente,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 38, 27, 'Para fartar [a terra] deserta e desolada, e para fazer crescer aos renovos da erva.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 38, 28, 'Por acaso a chuva tem pai? Ou quem gera as gotas do orvalho?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 38, 29, 'De qual ventre procede o gelo? E quem gera a geada do céu?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 38, 30, 'As águas se tornam duras como pedra, e a superfície do abismo se congela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 38, 31, 'Podes tu atar as cadeias das Plêiades, ou desatar as cordas do Órion?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 38, 32, 'Podes tu trazer as constelações a seu tempo, e guiar a Ursa com seus filhos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 38, 33, 'Sabes tu as ordenanças dos céus? Ou podes tu dispor do domínio deles sobre a terra?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 38, 34, 'Ou podes levantar tua voz até às nuvens, para que a abundância das águas te cubra?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 38, 35, 'Podes tu mandar relâmpagos, para que saiam, e te digam: Eis-nos aqui?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 38, 36, 'Quem pôs a sabedoria no íntimo? Ou quem deu entendimento à mente?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 38, 37, 'Quem pode enumerar as nuvens com sabedoria? E os odres dos céus, quem pode os despejar?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 38, 38, 'Quando o pó se endurece, e os torrões se apegam uns aos outros?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 38, 39, 'Caçarás tu a presa para o leão? Ou saciarás a fome dos leões jovens,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 38, 40, 'Quando estão agachados nas covas, [ou] estão à espreita no matagal?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 38, 41, 'Quem prepara aos corvos seu alimento, quando seus filhotes clamam a Deus, andando de um lado para o outro por não terem o que comer?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 39, 1, 'Sabes tu o tempo em que as cabras montesas dão filhotes? Ou observaste tu as cervas quando em trabalho de parto?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 39, 2, 'Contaste os meses que elas cumprem, e sabes o tempo de seu parto?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 39, 3, 'Quando se encurvam, produzem seus filhos, [e] lançam de si suas dores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 39, 4, 'Seus filhos se fortalecem, crescem como o trigo; saem, e nunca mais voltam a elas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 39, 5, 'Quem despediu livre ao asno montês? E quem ao asno selvagem soltou das ataduras?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 39, 6, 'Ao qual eu dei a terra desabitada por casa, e a terra salgada por suas moradas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 39, 7, 'Ele zomba do tumulto da cidade; não ouve os gritos do condutor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 39, 8, 'A extensão dos montes é seu pasto; e busca tudo o que é verde.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 39, 9, 'Por acaso o boi selvagem quererá te servir, ou ficará junto de tua manjedoura?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 39, 10, 'Ou amarrarás ao boi selvagem com sua corda para o arado? Ou lavrará ele aos campos atrás de ti?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 39, 11, 'Confiarás nele, por ser grande sua força, e deixarás que ele faça teu trabalho?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 39, 12, 'Porás tua confiança nele, para que ele colha tua semente, e a junte em tua eira?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 39, 13, 'As asas da avestruz batem alegremente, mas são suas asas e penas como as da cegonha?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 39, 14, 'Ela deixa seus ovos na terra, e os esquenta no chão,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 39, 15, 'E se esquece de que pés podem os pisar, e os animais do campo [podem] os esmagar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 39, 16, 'Age duramente para com seus filhos, como se não fossem seus, sem temer que seu trabalho tenha sido em vão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 39, 17, 'Porque Deus a privou de sabedoria, e não lhe repartiu entendimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 39, 18, 'Porém quando se levanta para correr, zomba do cavalo e do seu cavaleiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 39, 19, 'És tu que dás força ao cavalo, ou que vestes seu pescoço com crina?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 39, 20, 'Podes tu o espantar como a um gafanhoto? O sopro de suas narinas é terrível.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 39, 21, 'Ele escarva a terra, alegra-se de sua força, [e] sai ao encontro das armas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 39, 22, 'Ele zomba do medo, e não se espanta; nem volta para trás por causa da espada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 39, 23, 'Contra ele rangem a aljava, o ferro brilhante da lança e do dardo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 39, 24, 'Sacudido-se com furor, ele escarva a terra; ele não fica parado ao som da trombeta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 39, 25, 'Ao som das trombetas diz: Eia! E desde longe cheira a batalha, o grito dos capitães, e o barulho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 39, 26, 'Por acaso é por tua inteligência que o gavião voa, [e] estende suas asas para o sul?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 39, 27, 'Ou é por tua ordem que a água voa alto e põe seu ninho na altura?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 39, 28, 'Nas penhas ela mora e habita; no cume das penhas, e em lugares seguros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 39, 29, 'Desde ali espia a comida; seus olhos avistam de longe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 39, 30, 'Seus filhotes sugam sangue; e onde houver cadáveres, ali ela está.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 40, 1, 'Então o SENHOR respondeu mais a Jó, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 40, 2, 'Por acaso quem briga contra o Todo-Poderoso pode ensiná-lo? Quem quer repreender a Deus, responda a isto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 40, 3, 'Então Jó respondeu ao SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 40, 4, 'Eis que eu sou insignificante; o que eu te responderia? Ponho minha mão sobre minha boca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 40, 5, 'Uma vez falei, porém não responderei; até duas vezes, porém não prosseguirei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 40, 6, 'Então o SENHOR respondeu a Jó desde o redemoinho, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 40, 7, 'Cinge-te agora os teus lombos como homem; eu te perguntarei, e tu me explica.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 40, 8, 'Por acaso tu anularias o meu juízo? Tu me condenarias, para te justificares?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 40, 9, 'Tens tu braço como Deus? Ou podes tu trovejar com [tua] voz como ele?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 40, 10, 'Orna-te, pois, de excelência e alteza; e veste-te de majestade e glória.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 40, 11, 'Espalha os furores de tua ira; olha a todo soberbo, e abate-o.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 40, 12, 'Olha a todo soberbo, e humilha-o; e esmaga aos perversos em seu lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 40, 13, 'Esconde-os juntamente no pó; ata seus rostos no oculto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 40, 14, 'E eu também te reconhecerei; pois tua mão direita te terá livrado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 40, 15, 'Observa o beemote, ao qual eu fiz contigo; ele come erva come como o boi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 40, 16, 'Eis que sua força está em seus lombos, e seu poder na musculatura de seu ventre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 40, 17, 'Ele torna sua cauda dura como o cedro, e os nervos de suas coxas são entretecidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 40, 18, 'Seus ossos são [como] tubos de bronze; seus membros, como barras de ferro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 40, 19, 'Ele é a obra-prima dos caminhos de Deus; aquele que o fez o proveu de sua espada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 40, 20, 'Pois os montes lhe produzem pasto; por isso todos os animais do campo ali se alegram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 40, 21, 'Ele se deita debaixo das árvores sombrias; no esconderijo das canas e da lama.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 40, 22, 'As árvores sombrias o cobrem, cada uma com sua sombra; os salgueiros do ribeiro o cercam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 40, 23, 'Ainda que o rio se torne violento, ele não se apressa; confia ainda que o Jordão transborde até sua boca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 40, 24, 'Poderiam, por acaso, capturá-lo à vista de seus olhos, [ou] com laços furar suas narinas?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 41, 1, 'Poderás tu pescar ao leviatã com anzol, ou abaixar sua língua com uma corda?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 41, 2, 'Podes pôr um anzol em seu nariz, ou com um espinho furar sua queixada?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 41, 3, 'Fará ele súplicas a ti, [ou] falará contigo suavemente?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 41, 4, 'Fará ele pacto contigo, para que tu o tomes por escravo perpétuo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 41, 5, 'Brincarás tu com ele como com um passarinho, ou o atarás para tuas meninas?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 41, 6, 'Os companheiros farão banquete dele? Repartirão dele entre os mercadores?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 41, 7, 'Poderás tu encher sua pele de espetos, ou sua cabeça com arpões de pescadores?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 41, 8, 'Põe tua mão sobre ele; te lembrarás da batalha, e nunca mais voltarás a fazer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 41, 9, 'Eis que a esperança de alguém [de vencê-lo] falhará; pois, apenas ao vê-lo será derrubado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 41, 10, 'Ninguém há [tão] ousado que o desperte; quem pois, [ousa] se opor a mim?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 41, 11, 'Quem me deu primeiro, para que eu [o] recompense? Tudo o que há debaixo dos céus é meu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 41, 12, 'Eu não me calarei a respeito de seus membros, nem de [suas] forças, e da graça de sua estatura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 41, 13, 'Quem descobrirá sua vestimenta superficial? Quem poderá penetrar sua couraça dupla?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 41, 14, 'Quem poderia abrir as portas de seu rosto? Ao redor de seus dentes há espanto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 41, 15, 'Seus fortes escudos são excelentes; cada um fechado, como um selo apertado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 41, 16, 'Um está tão próximo do outro, que vento não pode entrar entre eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 41, 17, 'Estão grudados uns aos outros; estão tão travados entre si, que não se podem separar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 41, 18, 'Cada um de seus roncos faz resplandecer a luz, e seus olhos são como os cílios do amanhecer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 41, 19, 'De sua boca saem tochas, faíscas de fogo saltam dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 41, 20, 'De suas narinas sai fumaça, como de uma panela fervente ou de um caldeirão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 41, 21, 'Seu fôlego acende carvões, e de sua boca sai chama.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 41, 22, 'A força habita em seu pescoço; diante dele salta-se de medo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 41, 23, 'As dobras de sua carne estão apegadas [entre si] ; cada uma está firme nele, e não podem ser movidas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 41, 24, 'Seu coração é rígido como uma pedra, rígido como a pedra de baixo de um moinho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 41, 25, 'Quando ele se levanta, os fortes tremem; por [seus] abalos se recuam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 41, 26, 'Se alguém lhe tocar com a espada, não poderá prevalecer; nem arremessar dardo, ou lança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 41, 27, 'Ele considera o ferro como palha, e o aço como madeira podre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 41, 28, 'A flecha não o faz fugir; as pedras de funda são para ele como sobras de cascas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 41, 29, 'Considera toda arma como sobras de cascas, e zomba do mover da lança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 41, 30, 'Por debaixo de si tem conchas pontiagudas; ele esmaga com suas pontas na lama.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 41, 31, 'Ele faz ferver as profundezas como a uma panela, e faz do mar como um pote de unguento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 41, 32, 'Ele faz brilhar o caminho atrás de si; faz parecer ao abismo com cabelos grisalhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 41, 33, 'Não há sobre a terra algo que se possa comparar a ele. Ele foi feito para não temer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 41, 34, 'Ele vê tudo que é alto; ele é rei sobre todos os filhos dos animais soberbos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 42, 1, 'E Jó respondeu ao SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 42, 2, 'Eu sei que tudo podes, e nenhum de teus pensamentos pode ser impedido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 42, 3, '[Tu dizes] : Quem é esse que obscurece o conselho sem conhecimento? Por isso eu falei do que não entendia; coisas que eram maravilhosas demais para mim, e eu não as conhecia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 42, 4, 'Escuta-me, por favor, e eu falarei; eu te perguntarei, e tu me ensina.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 42, 5, 'Com os ouvidos eu ouvira falar de ti; mas agora meus olhos te veem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 42, 6, 'Por isso [me] abomino, e me arrependo no pó e na cinza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 42, 7, 'E sucedeu que, depois que o SENHOR acabou de falar essas palavras a Jó, o SENHOR disse a Elifaz, o temanita: Minha ira se acendeu contra ti e contra os teus dois amigos; porque não falastes de mim o que era correto, como o meu servo Jó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 42, 8, 'Por isso tomai sete bezerros e sete carneiros, ide ao meu servo Jó, e oferecei holocaustos em vosso favor, então meu servo Jó orará por vós; pois certamente atenderei a ele para eu não vos tratar conforme a vossa insensatez; pois não falastes de mim o que era correto, como o meu servo Jó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 42, 9, 'Então foram Elifaz, o temanita, Bildade, o suíta, e Zofar, o naamita, e fizeram como o SENHOR havia lhes dito; e o SENHOR atendeu a Jó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 42, 10, 'E o SENHOR livrou Jó de seu infortúnio, enquanto ele orava pelos seus amigos; e o SENHOR acrescentou a Jó o dobro de tudo quanto ele[ antes] possuía.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 42, 11, 'Então vieram e ele todos os seus irmãos, e todas as suas irmãs, e todos os que o conheciam antes; e comeram com ele pão em sua casa, e condoeram-se dele, e o consolaram acerca de toda a calamidade que o SENHOR tinha trazido sobre ele; e cada um deles lhe deu uma peça de dinheiro, e uma argola de ouro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 42, 12, 'E [assim] o SENHOR abençoou o último estado de Jó mais que o seu primeiro; porque teve catorze mil ovelhas, seis mil camelos, mil juntas de bois, e mil asnas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 42, 13, 'Também teve sete filhos e três filhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 42, 14, 'E chamou o nome da uma Jemima, e o nome da segunda Quézia, e o nome da terceira Quéren-Hapuque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 42, 15, 'E em toda a terra não se acharam mulheres tão belas como as filhas de Jó; e seu pai lhes deu herança entre seus irmãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 42, 16, 'E depois disto Jó viveu cento e quarenta anos; e viu seus filhos, e os filhos de seus filhos, até quatro gerações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 42, 17, 'Então Jó morreu, velho, e farto de dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 1, 1, 'Bem-aventurado o homem que não anda no conselho dos maus, nem fica parado no caminho dos pecadores, nem se senta junto dos escarnecedores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 1, 2, 'Mas sim, que tem seu prazer na Lei do SENHOR; e medita em sua Lei de dia e de noite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 1, 3, 'Porque ele será como uma árvore, plantada junto a ribeiros de águas, que dá fruto a seu [devido] tempo, e suas folhas não caem; e tudo quanto fizer prosperará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 1, 4, 'Os maus não são assim; mas são como a palha que o vento dispersa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 1, 5, 'Por isso os maus não subsistirão no julgamento, nem os pecadores no ajuntamento dos justos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 1, 6, 'Porque o SENHOR conhece o caminho dos justos; porém o caminho dos maus perecerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 2, 1, 'Por que as nações se rebelam, e os povos planejam em vão?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 2, 2, 'Os reis da terra se levantam, e os governantes tomam conselhos reunidos contra o SENHOR, e contra seu Ungido, [dizendo] :'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 2, 3, 'Rompamos as correntes deles, e lancemos fora de nós as cordas deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 2, 4, 'Aquele que está sentado nos céus rirá; o Senhor zombará deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 2, 5, 'Então ele lhes falará em sua ira; em seu furor ele os assombrará, [dizendo] :'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 2, 6, 'E eu ungi a meu Rei sobre Sião, o monte de minha santidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 2, 7, 'E eu declararei o decreto do SENHOR: Ele me disse: Tu és meu Filho; eu hoje te gerei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 2, 8, 'Pede-me, e eu te darei as nações [por] herança, e [por] tua propriedade os confins da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 2, 9, 'Com cetro de ferro tu as quebrarás; como vaso de oleiro tu as despedaçarás;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 2, 10, 'Portanto agora, reis, sede prudentes; vós, juízes da terra, deixai serdes instruídos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 2, 11, 'Servi ao SENHOR com temor; e alegrai-vos com tremor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 2, 12, 'Beijai ao Filho, para que ele não se ire, e pereçais [no] caminho; porque em breve a ira dele se acenderá. Bem-aventurados [são] todos os que nele confiam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 3, 1, 'Salmo de Davi, quando ele fugia da presença de seu filho Absalão: Ah SENHOR, como têm se multiplicado meus adversários! Muitos se levantam contra mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 3, 2, 'Muitos dizem de minha alma: Não há salvação para ele em Deus.(Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 3, 3, 'Porém tu, SENHOR, és escudo para mim; minha glória, e o que levanta minha cabeça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 3, 4, 'Com minha voz eu clamei ao SENHOR; e ele me ouviu desde o monte de sua santidade. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 3, 5, 'Eu me deitei, e dormi; acordei, porque o SENHOR me sustentava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 3, 6, 'Eu não temerei [ainda que sejam] dez mil pessoas que se ponham ao redor de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 3, 7, 'Levanta-te, SENHOR, salva-me, meu Deus; pois feriste os queixos de todos meus inimigos; [e] quebraste os dentes dos maus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 3, 8, 'A salvação [vem] do SENHOR; sobre o teu povo seja tua bênção. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 4, 1, 'Salmo de Davi para o regente, com instrumentos de cordas: Quando eu clamar, ouve-me, ó Deus de minha justiça; na angústia tu me alivias; tem misericórdia de mim, e ouve a minha oração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 4, 2, 'Filhos dos homens, até quando [tornareis] minha glória em infâmia, e amareis as coisas vãs? [Até quando] buscareis a mentira? (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 4, 3, 'Sabei pois, que o SENHOR separou para si aquele que é fiel; o SENHOR ouvirá, quando a ele eu clamar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 4, 4, 'Quando estiverdes perturbados, não pequeis; meditai em vosso coração sobre a vossa cama, e fazei silêncio. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 4, 5, 'Sacrificai sacrifícios de justiça, e confiai no SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 4, 6, 'Muitos dizem: Quem nos mostrará o bem?Levanta sobre nós, SENHOR, a luz de teu rosto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 4, 7, 'Tu me deste alegria em meu coração, maior do que quando o trigo e o vinho deles se multiplicaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 4, 8, 'Eu deitarei, e dormirei em paz; porque só tu, SENHOR, me fazes descansar seguro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 5, 1, 'Salmo de Davi para o regente, com instrumentos de sopro: SENHOR, escuta as minhas palavras; entende aquilo que estou meditando;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 5, 2, 'Ouve a voz do meu clamor, meu Rei e meu Deus; porque a ti eu oro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 5, 3, 'SENHOR, pela manhã ouvirás minha voz; pela manhã apresentarei [meu clamor] a ti, e ficarei esperando.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 5, 4, 'Porque tu não [és] Deus que tens prazer na maldade; contigo não habitará o mau.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 5, 5, 'Os arrogantes não ficarão de pé diante dos teus olhos; tu odeias todas os praticantes de maldade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 5, 6, 'Tu destruirás aos que falam mentiras; o SENHOR abomina ao homem sanguinário e enganador.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 5, 7, 'Mas eu, pela grandeza de tua bondade, entrarei em tua casa; adorarei inclinado para o templo de tua santidade em temor a ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 5, 8, 'SENHOR, guia-me em tua justiça, por causa dos meus adversários; prepara diante de mim o teu caminho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 5, 9, 'Porque não há verdade na boca deles; seu interior são meras destruições; a garganta deles é uma sepultura aberta; com suas línguas elogiam falsamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 5, 10, 'Declara-os culpados, ó Deus, [e] que caiam de seus próprios conselhos; expulsa-os por causa da abundância de suas transgressões, porque eles se rebelaram contra ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 5, 11, 'Mas se alegrem todos os que confiam em ti; clamai de alegria para sempre; porque tu os proteges; e fiquem contentes em ti aqueles que amam o teu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 5, 12, 'Porque tu, SENHOR, abençoarás ao justo; como com um escudo tu o rodearás com tua bondade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 6, 1, 'Salmo de Davi para o regente, com instrumentos de cordas, uma harpa de oito cordas: SENHOR, não me repreendas na tua ira; e não me castigues em teu furor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 6, 2, 'Tem misericórdia de mim, SENHOR; porque eu [estou] enfraquecido; cura-me, SENHOR, porque meus ossos estão afligidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 6, 3, 'Até minha alma está muito aflita; e tu, SENHOR, até quando?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 6, 4, 'Volta, SENHOR; livra minha alma; salva-me por tua bondade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 6, 5, 'Porque na morte não há lembrança de ti; no Xeol quem te louvará?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 6, 6, 'Já estou cansado do meu gemido; toda a noite eu inundo a minha cama; com minhas lágrimas molho meu leito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 6, 7, 'Meus olhos estão desolados de mágoa, [e] têm se envelhecido por causa de todos os meus adversários.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 6, 8, 'Sai para longe de mim, todos vós praticantes de maldade; porque o SENHOR já ouviu a voz do meu choro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 6, 9, 'O SENHOR tem ouvido a minha súplica; o SENHOR aceitará a minha oração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 6, 10, 'Todos os meus inimigos se envergonharão e ficarão muito perturbados; voltarão para trás, [e] repentinamente se envergonharão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 7, 1, 'Cântico de Davi, que cantou ao SENHOR, depois das palavras de Cuxe, descendente de Benjamim: SENHOR, meu Deus, em ti confio; salva-me de todos os que me perseguem, e livra-me.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 7, 2, 'Para que não rasguem minha alma como um leão, sendo despedaçada sem [haver] quem a livre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 7, 3, 'SENHOR, meu Deus, se eu fiz isto: se há perversidade em minhas mãos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 7, 4, 'Se eu paguei [com] mal ao que tinha paz comigo (mas fiz escapar ao que me oprimia sem causa);')
